  {
    "id": "task-phase-discipline",
    "severity": "advisory",
    "failureMessage": "the precondition is the ONLY decision point — a later-phase skip hides work from the run records and re-litigates a verdict already given",
    "scanFiles": "/(^|\\/)tasks\\/[^/]+\\/(task\\.md|[^/]+\\.mjs)$/",
    "excludeFiles": "/(^|\\/)tasks\\/[^/]+\\/task\\.mjs$/",
    "matchLines": [
      {
        "whenPathMatches": "/\\.md$/",
        "match": "/.*\\b([Ss]kip(s|ped|ping)?|stop( here)?|[Aa]bort|[Bb]ail( out)?|[Dd]o\\s+(\\*\\*?not\\*\\*?|not)\\s+(run|proceed|continue|stack)|[Ll]eav(e|ing)\\s+(it\\s+|this\\s+)?(cycle'?s?\\s+)?(converge\\s+)?undelivered)\\b.*/",
        "andLineMatches": "/\\b(if\\b|when\\b|unless\\b|already\\b|still\\s+(open|running|unreviewed)|(nothing|no\\s+new|not?\\s+\\w+)\\s+(changed|has\\s+changed)|before\\s+(anything|starting|researching)|unset\\s+means|absent\\b)\\b/i",
        "unlessLineMatches": "/\\bContext\\b|\\bprecondition\\b|needs-human/",
        "what": "instructs a conditional skip after the precondition already passed: \"{match}\"",
        "fix": "move the run/no-run decision into the task.json precondition, or reword an empty result as an empty outcome; a required input the dispatch lacks is a failure — park the item at task:status:needs-human-action"
      },
      {
        "whenPathMatches": "/\\.mjs$/",
        "match": "/.*(skip(ping)?\\s+this\\s+(cycle|run)|leaving\\s+this\\s+cycle|cycle\\s+skips|nothing\\s+to\\s+self-refresh).*/i",
        "what": "code-work announces a discretionary cycle skip: \"{match}\"",
        "fix": "let the precondition make that call, or complete the work and report an empty outcome; only a genuine failure may stop a run past the precondition"
      }
    ]
  },
  {
    "id": "legacy-check-spellings",
    "severity": "advisory",
    "since": "2026-09-03",
    "failureMessage": "the merged assertion families accept their pre-merge spelling only until no declaration still uses it, and a spelling the engine stops placing asserts nothing at all",
    "scanFiles": "/declared-checks\\.json$/",
    "matchLines": [
      {
        "match": "/\"eachValueInParsedArray\"/",
        "what": "{match} is the pre-merge spelling of an index-coverage assertion",
        "fix": "restate it as a named `extractValueSets` entry quantified over by `requireIndexCoverage`'s `eachValueOfSet` — the normalizer that rewrites it today is scheduled for removal (#1643)"
      }
    ]
  },
  {
    "id": "references-integrity",
    "severity": "blocking",
    "since": "2026-09-01",
    "failureMessage": "a dangling marker cites a rationale nobody recorded, and an orphaned check entry lets the periodic review reaffirm a check that no longer exists",
    "extractValueSets": [
      {
        "setName": "ruleMarkers",
        "fromLinesMatching": "/\\((?<value>\\d+(?:\\s*,\\s*\\d+)*)\\)\\s*$/",
        "inFilesMatching": "/^(?<packDir>(?:.*\\/)?packs\\/[^/]+\\/)RULES\\.md$/",
        "splitValuesOn": "/\\s*,\\s*/",
        "whenSetEmpty": "assertNothing"
      },
      {
        "setName": "skillMarkers",
        "fromLinesMatching": "/\\((?<value>\\d+(?:\\s*,\\s*\\d+)*)\\)\\s*$/",
        "inFilesMatching": "/^(?<packDir>(?:.*\\/)?packs\\/[^/]+\\/)skills\\/(?<skill>[^/]+)\\/SKILL\\.md$/",
        "splitValuesOn": "/\\s*,\\s*/",
        "whenSetEmpty": "assertNothing"
      },
      {
        "setName": "checkEntries",
        "fromLinesMatching": "/^\\s*-\\s+\\*\\*\\(check:(?<value>[\\w/-]+)\\)\\*\\*/",
        "inFilesMatching": "/^(?<packDir>(?:.*\\/)?packs\\/[^/]+\\/)references\\.md$/",
        "whenSetEmpty": "assertNothing"
      }
    ],
    "checkSetValues": [
      {
        "setName": "ruleMarkers",
        "requireSomeFileMatching": {
          "pathMatching": "/^{packDir}references\\.md$/",
          "text": "/^\\s*-\\s+\\*\\*\\(RULES-{value}\\)\\*\\*/m"
        },
        "what": "cites rationale entry ({value}), which {packDir}references.md does not carry as RULES-{value}",
        "fix": "add the \"- **(RULES-{value})** <reason>\" entry — creating {packDir}references.md if the pack has none — or drop the marker; entry numbers are stable identifiers, so a removed entry's number is never reused"
      },
      {
        "setName": "skillMarkers",
        "requireSomeFileMatching": {
          "pathMatching": "/^{packDir}references\\.md$/",
          "text": "/^\\s*-\\s+\\*\\*\\({skill}-{value}\\)\\*\\*/m"
        },
        "what": "cites rationale entry ({value}), which {packDir}references.md does not carry as {skill}-{value}",
        "fix": "add the \"- **({skill}-{value})** <reason>\" entry — creating {packDir}references.md if the pack has none — or drop the marker; entry numbers are stable identifiers, so a removed entry's number is never reused"
      },
      {
        "setName": "checkEntries",
        "requireSomeFileMatching": {
          "pathMatching": "/^{packDir}.*\\.(mjs|json)$/",
          "text": "/\\bid['\"]?\\s*:\\s*['\"]{value}['\"]/"
        },
        "what": "carries a rationale entry for check:{value}, which the pack does not carry",
        "fix": "remove the entry with the check it explained, or point it at the check's current id"
      }
    ]
  },
  {
    "id": "doc-pointers-resolve",
    "severity": "blocking",
    "since": "2026-09-04",
    "failureMessage": "the doc pointer is the More line a finding prints, and nothing opens it until the check fires — a stale one sits broken until a session follows it into nothing",
    "scanIgnoringComments": true,
    "extractValueSets": [
      {
        "setName": "docPointers",
        "fromLinesMatching": "/(?:^|[{,])\\s*doc:\\s*['\"](?<value>[^'\"#]+)/",
        "inFilesMatching": "/(^|\\/)packs\\/[^/]+\\/(?:worldRules|workRules|skills\\/[^/]+)\\/[^/]+\\.mjs$/",
        "whenSetEmpty": "assertNothing"
      }
    ],
    "checkSetValues": [
      {
        "setName": "docPointers",
        "requirePathExists": "{value}",
        "what": "doc: names {value}, which is not a path in this tree",
        "fix": "point doc: at the file that owns the rule's depth, repo-relative (a canon pack's under packs/<pack>/), or drop the field"
      }
    ]
  },
  {
    "id": "check-ships-with-test",
    "severity": "blocking",
    "since": "2026-09-04",
    "scope": "work",
    "failureMessage": "a check nobody watched fail meets its first false positive in a member's Stop hook, where every session pays for it",
    "fix": "write the fixture first — a violating tree must find and a clean one must not — and land it in the same change",
    "requireCoChange": [
      {
        "whenAddedLineMatches": { "inFilesMatching": "/(^|\\/)declared-checks\\.json$/", "match": "/^\\s*\"id\"\\s*:/" },
        "requireChangedFileMatching": "/\\.test\\.[cm]?[jt]sx?$|(^|\\/)tests?\\//",
        "what": "{path} declares a new check, and no test file changed with it"
      },
      {
        "whenAddedLineMatches": { "inFilesMatching": "/(^|\\/)(worldRules|workRules)\\/[^/]+\\.mjs$|(^|\\/)skills\\/[^/]+\\/checks\\.mjs$/", "match": "/^\\s*id:\\s*['\"]/" },
        "requireChangedFileMatching": "/\\.test\\.[cm]?[jt]sx?$|(^|\\/)tests?\\//",
        "what": "{path} adds a rule, and no test file changed with it"
      }
    ]
  }
]

