1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	
3	// Converted from this pack's no-toolchain prose, on its one mechanical half: a
4	// script may not probe for a Swift toolchain with `command -v swift` unless
5	// `xcode-select -p` has already gated it.
6	//
7	// `/usr/bin/swift` ships on every Mac as a *stub*. Run it without a developer
8	// directory and it does not fail — it pops the "install the command line
9	// developer tools?" panel, an 8 GB download prompted at whoever is trying to
10	// diagnose a broken app. So the probe is not a weaker test than `xcode-select
11	// -p`, it is a test of something else entirely: the stub's presence, which is
12	// universal. `xcode-select -p` fails quietly when no developer directory is
13	// configured, so it is the gate, and the probe may only run behind it.
14	//
15	// Same-or-earlier, not same-line: the gate has to *precede* the probe, and an
16	// `if xcode-select -p …; then` several lines up is as good as an `&&` on the
17	// same line. Backslash continuations are joined first, so a probe split across
18	// physical lines is still read as one command and reported against the line it
19	// started on.
20	//
21	// `#` comments are stripped before matching, in BOTH directions. A script that
22	// gets this right tends to document the trap directly above the gated call —
23	// "`command -v swift` is NOT a usable test" — and an unstripped scan flags that
24	// sentence instead of a violation. A commented-out gate is not a gate either,
25	// so the same stripping runs before the gate is credited.
26	//
27	// Blocking: the failure lands on the user's machine, at the worst moment, and
28	// nothing in a build or a test suite can see it.
29	
30	// The probes that ask "is there a swift?". `\bswiftc?\b` deliberately does not
31	// match `swiftlint`, `swift-format` or any other tool that merely starts that way.
32	const PROBE = /\b(?:command\s+-v|which|type\s+-p|hash)\s+(?:\/usr\/bin\/)?swiftc?\b/;
33	
34	// The gate that actually answers the question, in any of its spellings.
35	const GATE = /\bxcode-select\s+-p\b/;
36	
37	// A `#` comment: at the start of a line, or after whitespace. Leaves `${#var}`
38	// and a `#` glued to a word alone, which is as much shell as this needs to know.
39	const stripComment = (s) => s.replace(/(^|\s)#.*$/, '$1');
40	
41	const inScope = (f) => /\.(?:sh|bash|zsh)$/.test(f)
42	  || (f.startsWith('.github/workflows/') && /\.ya?ml$/.test(f));
43	
44	// Physical lines → logical lines, folding trailing-backslash continuations.
45	// Each entry keeps the 1-based physical line the command started on.
46	const logicalLines = (text) => {
