1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	
4	// Converted from this pack's app-bundle prose: `Package.swift`'s `platforms:`
5	// floor and `Info.plist`'s `LSMinimumSystemVersion` are two independent claims
6	// about the same minimum OS, and only ONE of them is enforced at launch. When
7	// they drift, the claim that is enforced wins in silence — Launch Services
8	// refuses (or admits) a Mac the package disagrees about, while `swift build`
9	// compiles happily against the other floor and no build step compares them.
10	//
11	// A plain two-files-must-agree invariant, and gated on both claims being present
12	// AND readable: no near-root `Package.swift` declaring a macOS floor, or a plist
13	// whose value is a build substitution (`$(MACOSX_DEPLOYMENT_TARGET)`) rather
14	// than a version, and there is nothing to compare. Absence is never a finding —
15	// which plist is "the app's Info.plist" is not something a scan can know, so the
16	// rule judges only a plist that already makes the claim.
17	//
18	// Parsed, not grepped, on both sides. `Package.swift` is read comments-stripped
19	// and the `.macOS(…)` calls are taken from inside the `platforms:` array's own
20	// brackets, so a `.macOS(` in a doc comment or in a target's build condition is
21	// not a floor. Plists have their XML comments blanked length-preservingly, so a
22	// commented-out key is not a claim and the finding's line still points at the
23	// real one. `14`, `14.0` and `14.0.0` are one floor — the comparison is on the
24	// trailing-zero-free form, not the string.
25	//
26	// Blocking: the drift ships a wrong floor to users, and nothing in the build,
27	// the test suite or the notarization lane reports it.
28	
29	// The pack's own fingerprint depth: a `Package.swift` at the repo root or one
30	// directory down (a monorepo's `mac/`), never deeper — so a fixture package
31	// nested in a test tree is not this repo's package.
32	const isPackageManifest = (f) => {
33	  const parts = f.split('/');
34	  return parts.at(-1) === 'Package.swift' && parts.length <= 2;
35	};
36	
37	const PLIST = /\.plist$/;
38	const PLATFORMS_KEY = /\bplatforms\s*:/;
39	const MACOS_CALL = /\.macOS\s*\(([^()]*)\)/g;
40	const LS_MINIMUM = /<\s*key\s*>\s*LSMinimumSystemVersion\s*<\s*\/\s*key\s*>\s*<\s*string\s*>\s*([^<]*?)\s*<\s*\/\s*string\s*>/;
41	const VERSION_LITERAL = /^\d+(?:\.\d+)*$/;
42	
43	// Length-preserving, so a finding's line number survives the blanking.
44	const blankXmlComments = (text) =>
45	  text.replace(/<!--[\s\S]*?-->/g, (m) => m.replace(/[^\n]/g, ' '));
46	
47	// The balanced `[ … ]` that follows `from`; null when there is none.
48	function bracketSpan(text, from) {
49	  const open = text.indexOf('[', from);
50	  if (open < 0) return null;
51	  let depth = 0;
52	  for (let i = open; i < text.length; i += 1) {
53	    if (text[i] === '[') depth += 1;
54	    else if (text[i] === ']') {
55	      depth -= 1;
56	      if (depth === 0) return text.slice(open + 1, i);
57	    }
58	  }
59	  return null;
60	}
61	
62	// `.v14` → [14]; `.v10_15` → [10, 15]; `"14.1"` → [14, 1]. Anything else — a
63	// named constant, `.custom(…)` — is a floor this check cannot read, and an
64	// unreadable floor is not a disagreement.
65	function platformVersion(arg) {
66	  const enumForm = /^\s*\.v(\d+)(?:_(\d+))?\s*$/.exec(arg);
67	  if (enumForm) {
68	    return enumForm[2] === undefined
69	      ? [Number(enumForm[1])]
70	      : [Number(enumForm[1]), Number(enumForm[2])];
71	  }
72	  const stringForm = /^\s*["'](\d+(?:\.\d+)*)["']\s*$/.exec(arg);
73	  return stringForm ? stringForm[1].split('.').map(Number) : null;
74	}
75	
76	const canonical = (parts) => {
77	  const p = [...parts];
78	  while (p.length > 1 && p.at(-1) === 0) p.pop();
79	  return p.join('.');
80	};
81	
82	const rule = {
83	  id: 'minimum-system-version-agrees',
84	  severity: 'blocking',
85	  description: "Info.plist's LSMinimumSystemVersion states the same OS floor as the package's platforms: [.macOS(…)]",
86	  doc: 'packs/macos/skills/macos-app-bundle/SKILL.md',
87	  why: 'the two are independent claims about the same minimum OS and only one of them is enforced at launch, so a drift ships a floor nobody chose and no build step compares them',
88	
89	  run(ctx) {
90	    // Every macOS floor the near-root package manifests declare, keyed by its
91	    // canonical form so 14 / 14.0 / 14.0.0 collapse to one answer.
92	    const floors = new Map();
93	    for (const file of ctx.files.filter(isPackageManifest)) {
94	      const raw = ctx.read(file);
95	      if (raw === null) continue;
96	      const text = stripComments(raw);
97	      const at = text.search(PLATFORMS_KEY);
98	      if (at < 0) continue;
99	      const list = bracketSpan(text, at);
100	      if (list === null) continue;
101	      for (const m of list.matchAll(MACOS_CALL)) {
102	        const version = platformVersion(m[1]);
103	        if (version) floors.set(canonical(version), { file, written: m[1].trim() });
104	      }
105	    }
106	    if (floors.size === 0) return [];
107	
108	    const out = [];
109	    for (const file of ctx.files.filter((f) => PLIST.test(f))) {
110	      const raw = ctx.read(file);
111	      if (raw === null) continue;
112	      const text = blankXmlComments(raw);
113	      const claim = LS_MINIMUM.exec(text);
114	      if (!claim || !VERSION_LITERAL.test(claim[1])) continue;
115	      if (floors.has(canonical(claim[1].split('.').map(Number)))) continue;
116	      const [expected, source] = [...floors.entries()][0];
117	      out.push(finding(rule, {
118	        file,
119	        line: text.slice(0, claim.index).split('\n').length,
120	        what: `LSMinimumSystemVersion is ${claim[1]}, but ${source.file} declares a macOS floor of ${expected} (.macOS(${source.written}))`,
121	        fix: `make the two claims one OS version — either <string>${expected}</string> here, or move the package's platforms: [.macOS(…)] to ${claim[1]}`,
122	      }));
123	    }
124	    return out;
125	  },
126	};
127	
128	export default rule;
129

