1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	import { isSource, lineOf, balanced } from '../lib.mjs';
4	
5	// `suppressLocalAudioPlayback` and `restrictOwnAudio` are `getDisplayMedia`
6	// SCREEN-CAPTURE constraints. They filter the playout of a captured tab out of
7	// that tab's audio track; they say nothing about a microphone, and getUserMedia
8	// ignores them entirely — no throw, no warning, no `OverconstrainedError`.
9	//
10	// They are reached for by name: someone hunting the app's own TTS leaking back
11	// through the mic reads "suppress local audio playback" / "restrict own audio"
12	// as exactly the fix, sets it on the mic capture, and ships believing self-echo
13	// is handled at the capture layer. It isn't, and the code that would have
14	// handled it (an application-level echo guard) never gets written. Speech
15	// failures are silent: nothing throws, nothing logs, and the feature simply
16	// does not exist.
17	//
18	// PARSED, NOT GREPPED. The names are only wrong where they reach a microphone
19	// capture, so the scan is the balanced argument list of a `getUserMedia(` call —
20	// plus, one hop, the initializer of any same-file constant that argument list
21	// references, since hoisting the constraints into a frozen constant is the
22	// ordinary way to write this:
23	//
24	//     const AUDIO = Object.freeze({ echoCancellation: true });
25	//     await media.getUserMedia({ audio: AUDIO });
26	//
27	// Everything outside that reach stays quiet on purpose — a file's real
28	// getDisplayMedia call, a `getSupportedConstraints()` probe, a screen-capture
29	// module's own constants table are all legitimate uses of these names, and a
30	// rule that grepped the file would false-alarm on every one of them. Comments
31	// are stripped first, so the paragraphs above cannot fire the rule.
32	
33	const CALL = /\bgetUserMedia\s*\(/g;
34	const DECL = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g;
35	const OPENER = /^\s*(?:[A-Za-z_$][\w$.]*\s*)?([[{(])/;
36	const DISPLAY_ONLY = ['suppressLocalAudioPlayback', 'restrictOwnAudio'];
37	
38	/**
39	 * The index ranges of `src` that a getUserMedia call's constraints actually
40	 * reach: the argument list itself, plus the initializer of every same-file
41	 * `const`/`let`/`var` the argument list names. One hop only — resolving further
42	 * needs real data-flow analysis, and a check that guesses is worse than one that
43	 * asks a simple, honest question.
44	 */
45	function reach(src, argsStart, args) {
46	  const regions = [{ start: argsStart, end: argsStart + args.length }];
47	  DECL.lastIndex = 0;
48	  for (let d = DECL.exec(src); d; d = DECL.exec(src)) {
49	    if (!new RegExp(`\\b${d[1]}\\b`).test(args)) continue;
50	    const eq = d.index + d[0].length;
51	    const head = OPENER.exec(src.slice(eq));
52	    if (!head) continue;
53	    const open = eq + head[0].length - 1;
54	    const init = balanced(src, open);
55	    if (init === null) continue;
56	    regions.push({ start: open, end: open + init.length });
57	  }
58	  return regions;
59	}
60	
61	const rule = {
62	  id: 'mic-constraints-not-screen-capture',
63	  severity: 'blocking',
64	  description: 'A microphone capture never asks for getDisplayMedia-only constraints',
65	  doc: 'packs/web-speech/RULES.md',
66	  why: 'suppressLocalAudioPlayback and restrictOwnAudio are getDisplayMedia screen-capture constraints — they filter a captured tab\'s own playout, not a microphone — so getUserMedia silently ignores them while the author believes self-echo is now handled at the capture layer and never writes the guard that would have handled it',
67	
68	  run(ctx) {
69	    const out = [];
70	    for (const file of ctx.files) {
71	      if (!isSource(file)) continue;
72	      const raw = ctx.read(file);
73	      if (raw === null || !DISPLAY_ONLY.some((name) => raw.includes(name))) continue;
74	      const src = stripComments(raw);
75	      const seen = new Set();
76	      CALL.lastIndex = 0;
77	      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
78	        const argsStart = m.index + m[0].length - 1;
79	        const args = balanced(src, argsStart);
80	        if (args === null) continue;
81	        for (const { start, end } of reach(src, argsStart, args)) {
82	          const region = src.slice(start, end);
83	          for (const name of DISPLAY_ONLY) {
84	            const at = region.search(new RegExp(`\\b${name}\\b`));
85	            if (at === -1) continue;
86	            const line = lineOf(src, start + at);
87	            if (seen.has(`${name}:${line}`)) continue;
88	            seen.add(`${name}:${line}`);
89	            out.push(finding(rule, {
90	              file,
91	              line,
92	              what: `a getUserMedia microphone capture asks for ${name}, which is a getDisplayMedia screen-capture constraint`,
93	              fix: `drop ${name} from the microphone constraints — it filters a captured tab's own playout out of a screen-capture track and getUserMedia ignores it outright, so it suppresses nothing here; residual self-echo has to be handled above the capture (an application-level echo guard), because the recognizer's capture takes no constraints at all`,
94	            }));
95	          }
96	        }
97	      }
98	    }
99	    return out;
100	  },
101	};
102	
103	export default rule;
104

