64	  for (const re of WIRES_RESULT) {
65	    re.lastIndex = 0;
66	    for (let m = re.exec(src); m; m = re.exec(src)) {
67	      if (INLINE_HANDLER.test(src.slice(m.index + m[0].length))) return true;
68	    }
69	  }
70	  return false;
71	}
