73	const rule = {
74	  id: 'stt-interim-results-gated',
75	  severity: 'blocking',
76	  description: 'A recognizer that enables interim results gates its handler on isFinal',
77	  doc: 'packs/web-speech/RULES.md',
78	  why: 'interim hypotheses are delivered on the same result event as the final transcript, so a handler that never checks isFinal treats every half-formed guess as a finished utterance — the app acts on words the user has not said yet and repeats itself as the guess is revised, with nothing thrown and nothing logged',
