81	    const out = [];
82	    for (const file of ctx.files) {
83	      if (!isSource(file)) continue;
84	      const raw = ctx.read(file);
85	      if (raw === null || !raw.includes('interimResults')) continue;
86	      const src = stripComments(raw);
87	      // Handled elsewhere: the gate belongs wherever the handler is written.
88	      if (!handlesResultInline(src)) continue;
89	      if (/\bisFinal\b/.test(src)) continue;
90	
91	      FLAG.lastIndex = 0;
92	      for (let m = FLAG.exec(src); m; m = FLAG.exec(src)) {
93	        if (OFF.test(m[1].trim())) continue;
94	        out.push(finding(rule, {
95	          file,
96	          line: lineOf(src, m.index),
97	          what: 'this file turns on interim results and handles the result event, but never checks isFinal',
98	          fix: 'test `isFinal` on each result in the handler and deliver only a final one to the caller — use the interim results solely as the "still speaking" signal (they are what a mid-utterance pause monitor watches); if interim hypotheses are not wanted at all, leave interimResults off rather than filtering them downstream',
99	        }));
100	        break; // one finding per file: the handler is the defect, not each flag
101	      }
102	    }
103	    return out;
104	  },
105	};
